module ysyx_25020039_ALU(
  input  [31:0] io_A,
                io_B,
  input  [3:0]  io_alu_control,
  output [31:0] io_result,
  output        io_zero_flag
);

  reg  [31:0] casez_tmp;
  wire [31:0] _GEN = {27'h0, io_B[4:0]};
  wire [62:0] _io_result_T_8 = {31'h0, io_A} << io_B[4:0];
  always @(*) begin
    casez (io_alu_control)
      4'b0000:
        casez_tmp = io_A + io_B;
      4'b0001:
        casez_tmp = io_A - io_B;
      4'b0010:
        casez_tmp = io_A & io_B;
      4'b0011:
        casez_tmp = {31'h0, $signed(io_A) < $signed(io_B)};
      4'b0100:
        casez_tmp = io_A ^ io_B;
      4'b0101:
        casez_tmp = {31'h0, io_A < io_B};
      4'b0110:
        casez_tmp = io_A | io_B;
      4'b0111:
        casez_tmp = $signed($signed(io_A) >>> _GEN);
      4'b1000:
        casez_tmp = io_A >> _GEN;
      4'b1001:
        casez_tmp = _io_result_T_8[31:0];
      4'b1010:
        casez_tmp = 32'h0;
      4'b1011:
        casez_tmp = 32'h0;
      4'b1100:
        casez_tmp = 32'h0;
      4'b1101:
        casez_tmp = 32'h0;
      4'b1110:
        casez_tmp = 32'h0;
      default:
        casez_tmp = 32'h0;
    endcase
  end // always @(*)
  assign io_result = casez_tmp;
  assign io_zero_flag = casez_tmp == 32'h0;
endmodule

module ysyx_25020039_PC(
  input  [3:0] io_jump,
  input        io_zero_flag,
               io_cmp_flag,
  output [2:0] io_pc_src
);

  assign io_pc_src =
    io_jump == 4'hA
      ? 3'h4
      : io_jump == 4'h8
          ? 3'h1
          : io_jump == 4'h9
              ? 3'h2
              : {2'h0,
                 io_jump == 4'h0
                   ? io_zero_flag
                   : io_jump == 4'h1
                       ? ~io_zero_flag
                       : io_jump == 4'h5 | io_jump == 4'h7
                           ? ~io_cmp_flag
                           : (io_jump == 4'h4 | io_jump == 4'h6) & io_cmp_flag};
endmodule

module ysyx_25020039_EXU(
