      2'b00:
        casez_tmp = 32'h0;
      2'b01:
        casez_tmp = io_in_bits_rd1;
      2'b10:
        casez_tmp = io_in_bits_rd1 | io_in_bits_csr_rd1;
      default:
        casez_tmp = io_in_bits_pc;
