  assign io_out_bits_signals_lsu_mem_wmask = io_in_bits_signals_lsu_mem_wmask;
  assign io_out_bits_signals_lsu_mem_rd = io_in_bits_signals_lsu_mem_rd;
  assign io_out_bits_signals_lsu_mem_write = io_in_bits_signals_lsu_mem_write;
  assign io_out_bits_signals_lsu_mem_valid = io_in_bits_signals_lsu_mem_valid;
  assign io_out_bits_signals_wbu_reg_write = io_in_bits_signals_wbu_reg_write;
  assign io_out_bits_signals_wbu_reg_write_sel = io_in_bits_signals_wbu_reg_write_sel;
